/**
 * VC-7: the DV-2 convergence signal also fires on the run_tests path and for an operator-configured verifier.
 * A run_tests-only loop on a failing verifier that never moves ends the turn BLOCKED with the attempt history;
 * a progressing history does not trigger it.
 */
import "./helpers/leak_guard.js";
import { test, describe } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import { AutonomousAgent } from "../src/agent.js";
import { DEFAULT_CONTINUATION, HarnessConfig } from "../src/types.js";
import { startGateway, makeRepo, Reply } from "./helpers/fixtures.js";

const quiet = (agent: AutonomousAgent) => {
  (agent as any).ui = new Proxy({}, { get: () => () => {} });
  return agent;
};
const cfg = (endpoint: string, workspace: string, extra: Partial<HarnessConfig> = {}): HarnessConfig => ({
  endpoint, model: "m", maxSteps: 30, temperature: 0, workspace, shell: "bash", approvalMode: "auto", fullAccess: true,
  continuation: { ...DEFAULT_CONTINUATION }, ...extra,
});
const write = (name: string): Reply => ({ kind: "tools", calls: [{ name: "write_file", args: { path: name, content: `${name}\n` } }] });
const runTests: Reply = { kind: "tools", calls: [{ name: "run_tests", args: {} }] };
const script = (...replies: Reply[]) => (n: number): Reply => replies[n - 1] ?? { kind: "text", content: "stopping" };
const FAILING = "test:\n\t@echo 'not ok 1 - adds numbers'\n\t@echo 'ℹ tests 1'\n\t@exit 1\n";

async function withAgent(makefile: string, replies: Reply[], extra: Partial<HarnessConfig>, fn: (agent: AutonomousAgent, gw: Awaited<ReturnType<typeof startGateway>>) => Promise<void>) {
  const repo = makeRepo({ Makefile: makefile });
  const gw = await startGateway(script(...replies));
  const agent = quiet(new AutonomousAgent(cfg(gw.url, repo, extra)));
  try {
    await fn(agent, gw);
  } finally {
    agent.shutdown();
    await gw.close();
    fs.rmSync(repo, { recursive: true, force: true });
  }
}

describe("VC-7 convergence on the run_tests path", () => {
  const loop = [write("a.txt"), runTests, write("b.txt"), runTests, write("c.txt"), runTests, write("d.txt"), runTests, write("e.txt"), runTests];

  test("a run_tests-only loop on an unchanged failing verifier ends BLOCKED with the history, not success", { timeout: 90_000 }, async () => {
    await withAgent(FAILING, loop, {}, async (agent, gw) => {
      const turn = await agent.runTurn("Make the build pass.");
      assert.equal(turn.execution, "BLOCKED");
      assert.equal(turn.outcome, "NOT_ESTABLISHED");
      assert.equal(turn.reason, "VERIFIER_NOT_CONVERGING");
      assert.equal(turn.convergence?.state, "stalled");
      assert.equal(turn.convergence?.attempts.length, 3);
      assert.deepEqual(turn.convergence?.attempts.map((a) => a.failingTests), [["adds numbers"], ["adds numbers"], ["adds numbers"]]);
      assert.equal(gw.requests.length, 6, "no inference request after the third failing run_tests");
    });
  });

  test("an operator-configured verifier run through run_tests is covered too", { timeout: 90_000 }, async () => {
    await withAgent(FAILING, loop, { authoritativeVerifierCommand: "make test" }, async (agent) => {
      const turn = await agent.runTurn("Make the build pass.");
      assert.equal(turn.reason, "VERIFIER_NOT_CONVERGING");
      assert.equal(turn.execution, "BLOCKED");
      assert.equal(turn.convergence?.attempts[0].command, "make test");
    });
  });

  test("the threshold comes from the continuation config", { timeout: 90_000 }, async () => {
    await withAgent(FAILING, loop, { continuation: { ...DEFAULT_CONTINUATION, verifierConvergenceAttempts: 2 } }, async (agent, gw) => {
      const turn = await agent.runTurn("Make the build pass.");
      assert.equal(turn.reason, "VERIFIER_NOT_CONVERGING");
      assert.equal(turn.convergence?.attempts.length, 2);
      assert.equal(gw.requests.length, 4);
    });
  });

  test("a progressing history (a different failing test each run) does not trigger it", { timeout: 90_000 }, async () => {
    const changing = "test:\n\t@echo \"not ok 1 - t$$(ls | wc -l)\"\n\t@echo 'ℹ tests 1'\n\t@exit 1\n";
    await withAgent(changing, [write("a.txt"), runTests, write("b.txt"), runTests, write("c.txt"), runTests, { kind: "text", content: "I will leave it here." }], {}, async (agent, gw) => {
      const turn = await agent.runTurn("Make the build pass.");
      assert.notEqual(turn.reason, "VERIFIER_NOT_CONVERGING");
      assert.notEqual(turn.execution, "BLOCKED");
      assert.equal(turn.convergence, undefined);
      assert.ok(gw.requests.length >= 7, "the model was still asked to continue");
    });
  });
});
